	self.L(4457).ValidateAll("ARRAYS_ZIP([1, 2, 3])", Kw("write", NewDict("snowflake", "ARRAYS_ZIP([1, 2, 3])", "duckdb", "CASE WHEN [1, 2, 3] IS NULL THEN NULL WHEN LENGTH([1, 2, 3]) = 0 THEN [{'$1': NULL}] ELSE LIST_TRANSFORM(RANGE(0, LENGTH([1, 2, 3])), LAMBDA __i : {'$1': COALESCE([1, 2, 3], [])[__i + 1]}) END")))
