func test_snowflake_TestSnowflake_test_match_recognize(self *Case, a Args) Value {
	var window_frame, row, after Value
	_ = []Value{window_frame, row, after}
	for _, item_ := range Iter(NewTuple("", "FINAL ", "RUNNING ")) {
		window_frame = item_
		for _, item_ := range Iter(NewTuple("ONE ROW PER MATCH", "ALL ROWS PER MATCH", "ALL ROWS PER MATCH SHOW EMPTY MATCHES", "ALL ROWS PER MATCH OMIT EMPTY MATCHES", "ALL ROWS PER MATCH WITH UNMATCHED ROWS")) {
			row = item_
			for _, item_ := range Iter(NewTuple("AFTER MATCH SKIP", "AFTER MATCH SKIP PAST LAST ROW", "AFTER MATCH SKIP TO NEXT ROW", "AFTER MATCH SKIP TO FIRST x", "AFTER MATCH SKIP TO LAST x")) {
				after = item_
				self.SubTest(func() {
					self.Do(5618, func() {
						self.ValidateIdentity(F("SELECT\n  *\nFROM x\nMATCH_RECOGNIZE (\n  PARTITION BY a, b\n  ORDER BY\n    x DESC\n  MEASURES\n    ", FV{V: window_frame}, "y AS b\n  ", FV{V: row}, "\n  ", FV{V: after}, "\n  PATTERN (^ S1 S2*? ( {- S3 -} S4 )+ | PERMUTE(S1, S2){1,2} $)\n  DEFINE\n    x AS y\n)"), Kw("pretty", true))
					})
				}, F("MATCH_RECOGNIZE with window frame ", FV{V: window_frame}, ", rows ", FV{V: row}, ", after ", FV{V: after}, ": "))
			}
		}
	}
	return nil
}

