func test_snowflake_TestSnowflake_test_directed_joins(self *Case, a Args) Value {
	var join_side, outer, natural, prefix Value
	_ = []Value{join_side, outer, natural, prefix}
	self.L(7275).ValidateIdentity("SELECT * FROM a CROSS DIRECTED JOIN b USING (id)")
	self.L(7276).ValidateIdentity("SELECT * FROM a INNER DIRECTED JOIN b USING (id)")
	self.L(7277).ValidateIdentity("SELECT * FROM a NATURAL INNER DIRECTED JOIN b USING (id)")
	for _, item_ := range Iter(NewTuple("LEFT", "RIGHT", "FULL")) {
		join_side = item_
		for _, item_ := range Iter(NewTuple("", " OUTER")) {
			outer = item_
			for _, item_ := range Iter(NewTuple("", "NATURAL ")) {
				natural = item_
				self.Do(7282, func() { prefix = Add(Add(Add(natural, join_side), outer), " DIRECTED") })
				self.SubTest(func() {
					self.Do(7284, func() { self.ValidateIdentity(F("SELECT * FROM a ", FV{V: prefix}, " JOIN b USING (id)")) })
				}, F("Testing ", FV{V: prefix}, " JOIN"))
			}
		}
	}
	return nil
}

